    },
    scaleImageData,
    targetBytes: params.targetBytes,
    maxUploadBytes: params.maxUploadBytes,
    maxOutputBytes: params.maxOutputBytes,
    minQuality: params.minQuality,
    minEdgePx: params.minEdgePx,
    signal: params.signal,
  });
}

