export async function encodeWebpWithWorkerFallback(
  params: WorkerEncodeParams,
): Promise<WebpBudgetResult> {
  if (params.signal?.aborted) {
    return {
      ok: false,
      reason: 'aborted',
      message: 'Bildoptimierung abgebrochen.',
    };
  }

